CREATE TABLE "AspNetUsers" (
  "Id" text PRIMARY KEY, "DisplayName" varchar(80) NOT NULL, "Disabled" boolean NOT NULL,
  "EmailNotifications" boolean NOT NULL, "CreatedAt" timestamptz NOT NULL,
  "UserName" varchar(256), "NormalizedUserName" varchar(256), "Email" varchar(256), "NormalizedEmail" varchar(256),
  "EmailConfirmed" boolean NOT NULL, "PasswordHash" text, "SecurityStamp" text, "ConcurrencyStamp" text,
  "PhoneNumber" text, "PhoneNumberConfirmed" boolean NOT NULL, "TwoFactorEnabled" boolean NOT NULL,
  "LockoutEnd" timestamptz, "LockoutEnabled" boolean NOT NULL, "AccessFailedCount" integer NOT NULL
);
CREATE UNIQUE INDEX "UserNameIndex" ON "AspNetUsers" ("NormalizedUserName");
CREATE INDEX "EmailIndex" ON "AspNetUsers" ("NormalizedEmail");
CREATE TABLE "AspNetRoles" ("Id" text PRIMARY KEY, "Name" varchar(256), "NormalizedName" varchar(256), "ConcurrencyStamp" text);
CREATE UNIQUE INDEX "RoleNameIndex" ON "AspNetRoles" ("NormalizedName");
CREATE TABLE "AspNetUserRoles" ("UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "RoleId" text NOT NULL REFERENCES "AspNetRoles" ON DELETE CASCADE, PRIMARY KEY ("UserId", "RoleId"));
CREATE INDEX "IX_AspNetUserRoles_RoleId" ON "AspNetUserRoles" ("RoleId");
CREATE TABLE "AspNetUserClaims" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "ClaimType" text, "ClaimValue" text);
CREATE INDEX "IX_AspNetUserClaims_UserId" ON "AspNetUserClaims" ("UserId");
CREATE TABLE "AspNetRoleClaims" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "RoleId" text NOT NULL REFERENCES "AspNetRoles" ON DELETE CASCADE, "ClaimType" text, "ClaimValue" text);
CREATE INDEX "IX_AspNetRoleClaims_RoleId" ON "AspNetRoleClaims" ("RoleId");
CREATE TABLE "AspNetUserLogins" ("LoginProvider" text NOT NULL, "ProviderKey" text NOT NULL, "ProviderDisplayName" text, "UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, PRIMARY KEY ("LoginProvider", "ProviderKey"));
CREATE INDEX "IX_AspNetUserLogins_UserId" ON "AspNetUserLogins" ("UserId");
CREATE TABLE "AspNetUserTokens" ("UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "LoginProvider" text NOT NULL, "Name" text NOT NULL, "Value" text, PRIMARY KEY ("UserId", "LoginProvider", "Name"));
CREATE TABLE "Groups" ("Id" uuid PRIMARY KEY, "Name" varchar(100) NOT NULL, "Version" uuid NOT NULL, "Disabled" boolean NOT NULL, "CreatedAt" timestamptz NOT NULL);
CREATE TABLE "Members" ("GroupId" uuid NOT NULL REFERENCES "Groups" ON DELETE CASCADE, "UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "Role" text NOT NULL CHECK ("Role" IN ('owner', 'member')), "JoinedAt" timestamptz NOT NULL, PRIMARY KEY ("GroupId", "UserId"));
CREATE INDEX "IX_Members_UserId" ON "Members" ("UserId");
CREATE TABLE "Lists" ("Id" uuid PRIMARY KEY, "GroupId" uuid NOT NULL REFERENCES "Groups" ON DELETE CASCADE, "Name" varchar(100) NOT NULL, "Completed" boolean NOT NULL, "CompletedAt" timestamptz, "DeletedAt" timestamptz, "CreatedAt" timestamptz NOT NULL, "LastSummaryActivityId" bigint NOT NULL, "RunStarted" boolean NOT NULL);
CREATE INDEX "IX_Lists_GroupId_DeletedAt" ON "Lists" ("GroupId", "DeletedAt");
CREATE TABLE "Products" ("Id" uuid PRIMARY KEY, "ListId" uuid NOT NULL REFERENCES "Lists" ON DELETE CASCADE, "Text" varchar(200) NOT NULL, "NormalizedText" varchar(64) NOT NULL, "Version" uuid NOT NULL, "AddedBy" text NOT NULL, "Purchased" boolean NOT NULL, "PurchasedBy" text, "PurchasedAt" timestamptz, "DeletedAt" timestamptz, "CreatedAt" timestamptz NOT NULL);
CREATE INDEX "IX_Products_ListId_NormalizedText" ON "Products" ("ListId", "NormalizedText");
CREATE TABLE "Archives" ("ListId" uuid NOT NULL REFERENCES "Lists" ON DELETE CASCADE, "UserId" text NOT NULL, PRIMARY KEY ("ListId", "UserId"));
CREATE TABLE "Sessions" ("Id" uuid PRIMARY KEY, "ListId" uuid NOT NULL REFERENCES "Lists" ON DELETE CASCADE, "UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE RESTRICT, "StartedAt" timestamptz NOT NULL, "EndedAt" timestamptz);
CREATE UNIQUE INDEX "IX_Sessions_ListId_UserId" ON "Sessions" ("ListId", "UserId") WHERE "EndedAt" IS NULL;
CREATE INDEX "IX_Sessions_UserId" ON "Sessions" ("UserId");
CREATE TABLE "Invitations" ("Id" uuid PRIMARY KEY, "GroupId" uuid NOT NULL REFERENCES "Groups" ON DELETE CASCADE, "TokenHash" text NOT NULL, "Email" text, "ExpiresAt" timestamptz NOT NULL, "RevokedAt" timestamptz, "MaxUses" integer NOT NULL CHECK ("MaxUses" > 0), "Uses" integer NOT NULL CHECK ("Uses" >= 0), "CreatedAt" timestamptz NOT NULL);
CREATE UNIQUE INDEX "IX_Invitations_TokenHash" ON "Invitations" ("TokenHash");
CREATE INDEX "IX_Invitations_GroupId" ON "Invitations" ("GroupId");
CREATE TABLE "Activities" ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "GroupId" uuid NOT NULL REFERENCES "Groups" ON DELETE CASCADE, "ListId" uuid, "ActorId" text NOT NULL, "ActorName" text NOT NULL, "Kind" text NOT NULL, "Text" text NOT NULL, "At" timestamptz NOT NULL);
CREATE INDEX "IX_Activities_GroupId_Id" ON "Activities" ("GroupId", "Id");
CREATE INDEX "IX_Activities_ListId_Id" ON "Activities" ("ListId", "Id");
CREATE TABLE "Notifications" ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "UserId" text NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "GroupId" uuid NOT NULL, "ListId" uuid, "Kind" text NOT NULL, "Text" text NOT NULL, "At" timestamptz NOT NULL, "ReadAt" timestamptz);
CREATE INDEX "IX_Notifications_UserId_ReadAt" ON "Notifications" ("UserId", "ReadAt");
CREATE TABLE "Emails" ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "GroupId" uuid, "UserId" text, "To" text NOT NULL, "Subject" text NOT NULL, "Body" text NOT NULL, "Attempts" integer NOT NULL, "AvailableAt" timestamptz NOT NULL, "SentAt" timestamptz, "LastError" text);
CREATE INDEX "IX_Emails_SentAt_AvailableAt" ON "Emails" ("SentAt", "AvailableAt");
CREATE TABLE "AdminAudits" ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "ActorId" text NOT NULL, "Action" text NOT NULL, "Target" text NOT NULL, "At" timestamptz NOT NULL);
